#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    int n, k;
    scanf("%d %d", &n, &k);
    vector<ll> a(n);
    for (auto &x : a) scanf("%lld", &x);
    const ll INF = LLONG_MAX / 4;
    vector<ll> dp(n + 1, INF);
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        // Last segment a[j..i-1]: walk j backward, keeping its maximum.
        ll largest = LLONG_MIN, best = INF;
        for (int j = i - 1; j >= max(0, i - k); j--) {
            largest = max(largest, a[j]);
            best = min(best, dp[j] + largest);
        }
        dp[i] = best;
    }
    printf("%lld\n", dp[n]);
}

import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), k = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        final long INF = Long.MAX_VALUE / 4;
        long[] dp = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            // Last segment a[j..i-1]: walk j backward, keeping its maximum.
            long largest = Long.MIN_VALUE, best = INF;
            for (int j = i - 1; j >= Math.max(0, i - k); j--) {
                largest = Math.max(largest, a[j]);
                best = Math.min(best, dp[j] + largest);
            }
            dp[i] = best;
        }
        System.out.println(dp[n]);
    }
}

package main

import (
	"fmt"
	"io"
	"math"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := int(nextInt()), int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	const INF = math.MaxInt64 / 4
	dp := make([]int64, n+1)
	for i := 1; i <= n; i++ {
		// Last segment a[j..i-1]: walk j backward, keeping its maximum.
		largest, best := int64(math.MinInt64), int64(INF)
		for j := i - 1; j >= max(0, i-k); j-- {
			largest = max(largest, a[j])
			best = min(best, dp[j]+largest)
		}
		dp[i] = best
	}
	fmt.Println(dp[n])
}
